import torch
import torch.nn as nn

# Test the ConvTranspose3d formula
C_in, C_out, K = 2, 3, 3
D_in, H_in, W_in = 4, 4, 4
D_out, H_out, W_out = 6, 6, 6
N = 1

torch.manual_seed(42)
x = torch.randn(N, C_in, D_in, H_in, W_in)
w = torch.randn(C_in, C_out, K, K, K)

# PyTorch reference
ref_conv = nn.ConvTranspose3d(C_in, C_out, K, bias=False)
ref_conv.weight.data = w.clone()
ref_out = ref_conv(x)
ref_relu = nn.ReLU()(ref_out)

# Manual computation with the formula:
# output[n, oc, d, h, w] = sum_{ic, kd, kh, kw} input[n, ic, d-kd, h-kh, w-kw] * weight[ic, oc, kd, kh, kw]
# where 0 <= d-kd < D_in, etc.
manual_out = torch.zeros(N, C_out, D_out, H_out, W_out)
pad = 0
for n in range(N):
    for oc in range(C_out):
        for d in range(D_out):
            for h in range(H_out):
                for w in range(W_out):
                    acc = 0.0
                    for ic in range(C_in):
                        for kd in range(K):
                            din = d + pad - kd
                            if 0 <= din < D_in:
                                for kh in range(K):
                                    hin = h + pad - kh
                                    if 0 <= hin < H_in:
                                        for kw in range(K):
                                            win = w + pad - kw
                                            if 0 <= win < W_in:
                                                acc += x[n, ic, din, hin, win].item() * w[ic, oc, kd, kh, kw].item()
                    manual_out[n, oc, d, h, w] = max(0.0, acc)

diff = (manual_out - ref_relu).abs()
print(f'Manual vs ref: max diff = {diff.max().item():.10f}')
print(f'All close: {torch.allclose(manual_out, ref_relu)}')

# Now test the WEIGHT INDEX order: maybe it's w[oc, ic] not w[ic, oc]?
# In ConvTranspose, weight is (in_c, out_c, kd, kh, kw)
# But internally PyTorch might use it differently?
# Let me check: the nn.ConvTranspose3d computes:
# out[oc] = conv_transpose(in[ic], weight[ic, oc])
# where weight[ic, oc] is the filter mapping ic -> oc
# This matches our formula.

# Let's also test with the alternative: w[oc, ic]
manual_out2 = torch.zeros(N, C_out, D_out, H_out, W_out)
for n in range(N):
    for oc in range(C_out):
        for d in range(D_out):
            for h in range(H_out):
                for w in range(W_out):
                    acc = 0.0
                    for ic in range(C_in):
                        for kd in range(K):
                            din = d - kd
                            if 0 <= din < D_in:
                                for kh in range(K):
                                    hin = h - kh
                                    if 0 <= hin < H_in:
                                        for kw in range(K):
                                            win = w - kw
                                            if 0 <= win < W_in:
                                                acc += x[n, ic, din, hin, win].item() * w[ic, oc, kd, kh, kw].item()
                    manual_out2[n, oc, d, h, w] = max(0.0, acc)

diff2 = (manual_out2 - ref_relu).abs()
print(f'Manual2 (w[ic,oc]) vs ref: max diff = {diff2.max().item():.10f}')
